"use strict";
(function(){
const F=window.CLASS_ON_FIXTURES,KEY="class-on-demo-v1.2";
const defaults={applied:false,result:false,debugChoice:"",version:"1.0",tasks:[],noticeFilter:"전체",seatFirst:"",seatSecond:"",auctionBid:"",presentOpen:new URLSearchParams(location.search).get("mode")==="present",step:"대기 · 초기 상태"};
let state=load(),memoryNote="";const main=document.getElementById("main"),modalLayer=document.getElementById("modal-layer"),toast=document.getElementById("toast"),presenterMode=new URLSearchParams(location.search).get("mode")==="present";document.body.classList.toggle("presenter-mode",presenterMode);
function load(){try{return{...defaults,...JSON.parse(sessionStorage.getItem(KEY)||"{}")}}catch(_){return{...defaults}}}
function debug2(){const picked=state.debugChoice,enacted=state.version==="1.1";return`${header("제도 디버그 데이","우리 반 업무 방식을 바꿔보기",`<div class="version-display"><span>현재 버전</span><strong>CLASS:ON ${state.version}</strong></div>`)}${crumb("최근 4주 업무 기록")}<section class="debug-hero"><div><span class="kicker rose">문제 발견</span><h2>숙련업무 배정이 일부 학생들에게 반복됐습니다</h2><p>현재 업무 방식으로는 처음 해보는 학생의 배울 기회가 적습니다.</p></div><div class="evidence-card"><span>업무 기록 요약</span><strong>새로 도전한 학생이 부족해요</strong><div><span>같은 학생에게 반복</span><b>확인</b></div><div><span>배울 기회 부족</span><b>확인</b></div><small>최근 4주 업무 기록을 개인을 알아볼 수 없게 정리한 결과입니다.</small></div></section>${enacted?`<section class="version-success"><span class="spark" aria-hidden="true">✓</span><div><span>새 운영방법 저장 완료</span><h2>CLASS:ON 1.0 <b>→</b> 1.1</h2><p>4주 동안 함께 일해 본 뒤, 새로 도전한 학생 수와 확인에 걸린 시간을 보고 계속할지 결정합니다.</p></div></section><div class="trial-grid"><section><span>이번에 바꾼 방법</span><strong>숙련 학생 + 견습생</strong><small>견습생이 실무 일부를 경험하며 업무를 배워가요.</small></section><section><span>시험 기간</span><strong>9월 21일 → 10월 16일</strong><small>4주 동안 기록합니다</small></section><section><span>다음 확인</span><strong>10월 19일</strong><small>계속할지, 다시 바꿀지 결정합니다</small></section></div><div class="rights-banner compact-banner"><span class="rights-icon">✓</span><div><strong>필요한 지원은 바뀌지 않아요</strong><p>이번엔 업무 방식만 바꿔보는 거예요.</p></div></div>`:`<section class="choice-section"><div class="section-heading"><div><span class="kicker blue">학생들이 고르는 방법</span><h2>다음 공개채용부터 어떻게 바꿔볼까요?</h2></div><small></small></div><div class="choice-grid"><button class="choice ${picked==="apprentice"?"selected":""}" data-choice="apprentice"><span class="choice-check">${picked==="apprentice"?"✓":"1"}</span><div><h3>견습 과정 신설</h3><p>숙련된 학생과 신입 견습생이 한 팀을 이루어, 견습생이 실무 일부를 직접 경험하며 업무를 배울 수 있도록 지원합니다.</p><dl><div><dt>좋은 점</dt><dd>새로 도전할 기회가 늘어요</dd></div><div><dt>살펴볼 점</dt><dd>숙련 학생의 업무가 늘어나요</dd></div><div><dt>기간</dt><dd>4주</dd></div></dl></div></button><button class="choice ${picked==="split"?"selected":""}" data-choice="split"><span class="choice-check">${picked==="split"?"✓":"2"}</span><div><h3>한 일을 두 단계로 나누기</h3><p>업무를 한 학생에게 한 번에 다 맡기지 않고, 짧은 준비 작업과 마무리 작업으로 나누어 공고합니다.</p><dl><div><dt>좋은 점</dt><dd>진입장벽이 낮아져요</dd></div><div><dt>살펴볼 점</dt><dd>두 작업을 잘 이어야 해요</dd></div><div><dt>기간</dt><dd>4주</dd></div></dl></div></button></div><button class="primary enact" data-action="enact" ${picked!=="apprentice"?"disabled":""}>이 방법으로 4주 시험하기 <span aria-hidden="true">→</span></button><p class="fine center"></p></section>`}`}
function save(){sessionStorage.setItem(KEY,JSON.stringify(state));updatePresenter()}
function reset(){sessionStorage.removeItem(KEY);state={...defaults,presentOpen:state.presentOpen};memoryNote="";save();location.hash="home";render();announce("데모를 최초 상태로 초기화했습니다.")}
function round(n){return Math.round(n*10)/10}function fmt(n){return Number.isInteger(n)?String(n):n.toFixed(1)}
function money(){const tax=round(F.student.grossWage*F.student.taxRate),net=round(F.student.grossWage-tax),spent=F.student.musicSpend+F.student.projectSpend+F.student.residentTax;return{tax,net,spent,balance:round(F.student.initialBalance-spent+(state.result?net:0))}}
function route(){return(location.hash||"#home").slice(1).split("?")[0]}function section(r){if(["jobs","job","wallet","activities","seating","budget","debug"].includes(r))return"classon";if(r.startsWith("backup"))return"";return r}
function go(hash){location.hash=hash}function setStep(step){state.step=step;save()}function announce(message){toast.textContent=message;toast.hidden=false;clearTimeout(announce.timer);announce.timer=setTimeout(()=>toast.hidden=true,2600)}
function header(eyebrow,title,extra=""){return`<header class="topbar"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1></div>${extra||`<div class="profile"><span class="avatar" aria-hidden="true">김</span><span><strong>김민준</strong><small>가상학생</small></span></div>`}</header>`}
function rights(){return`<section class="rights-banner" aria-label="권리 안내"><span class="rights-icon" aria-hidden="true">✓</span><div><strong>0 ON이어도 권리는 그대로</strong><p>수업 참여, 발언, 투표, 상담 등의 필수 지원은 ON 잔액이나 고용 여부와 관계없이 동일하게 보장됩니다.</p></div></section>`}
function crumb(label){return`<div class="crumb"><a class="back-link" href="#classon">← CLASS:ON으로</a><p class="page-kicker">${label}</p></div>`}
function home(){const m=money();return`${header("일반계 고1 · 26명 가상학급","좋은 아침이에요, 김민준님")}${rights()}<section class="dashboard-head"><div><p class="date">2026년 9월 14일 월요일</p><h2>오늘의 우리 반</h2></div><button class="wallet-chip" data-go="wallet"><span>나에게만 보이는 잔액</span><strong>${fmt(m.balance)} ON</strong></button></section><div class="dashboard-grid"><section class="card schedule-card"><div class="card-title"><div><span class="kicker blue">다음 수업</span><h3>5교시 · 통합사회</h3></div><span class="time-pill">13:40</span></div><p>1학년 3반 교실 · 작은 사회의 규칙</p><div class="mini-list"><span>6교시 체육</span><span>체육복 준비</span></div></section><section class="card lunch-card"><div class="card-title"><div><span class="kicker orange">가상 급식 정보</span><h3>오늘의 점심</h3></div><button class="icon-button" data-action="meal" aria-label="급식 자세히 보기">＋</button></div><p class="menu-text">${F.meal.menu.join(" · ")}</p><small>알레르기 예시 ${F.meal.allergy} · 발표용 식단</small></section><section class="card notice-card"><div class="card-title"><div><span class="kicker violet">중요 공지</span><h3>수행평가 준비물</h3></div><button class="status" data-action="notice">상세 보기</button></div><p>내일 통합과학 실험에 사용할 보안경과 필기도구를 준비해 주세요.</p><small>오늘 08:10 · 담임 · 가상 공지</small></section><section class="card duty-card"><div class="card-title"><div><span class="kicker green">공동 시민의무</span><h3>교실 바닥 · 6명</h3></div><span class="time-pill">15:40</span></div><p>청소는 ON을 받는 일이 아니라 모두가 함께 행하는 책임입니다.</p><button class="text-button" data-go="life">도움 요청하기 →</button></section><section class="card job-card featured"><div class="job-meta"><span class="kicker navy">지원 가능한 일</span><span class="status open">주요 공고 2건</span></div><h3>이번 주 공개채용</h3><p>민준은 공개된 업무 중 원하는 공고를 확인해 지원할 수 있습니다.</p><div class="job-options"><button class="job-option primary-choice" data-go="job"><span><strong>웹 게시 작업</strong><small>숙련업무 · 35~45분 · 12 ON</small></span><span class="status ${state.applied?"done":"open"}">${state.result?"결과 확인":state.applied?"지원 완료":"모집 중"}</span></button><button class="job-option" data-action="accessibility"><span><strong>학급 접근성 지원</strong><small>일반업무 · 20~30분 · 8 ON</small></span><span class="status open">모집 중</span></button></div><p class="fine">필요한 개인지원은 담임·학교가 먼저 보장하며, 공고에는 개인의 장애·건강정보를 넣지 않습니다.</p></section><section class="card upcoming-card"><div class="card-title"><div><span class="kicker rose">가까운 일정</span><h3>학급회의</h3></div><span class="d-day">D-2</span></div><p>9월 16일 수요일 · 7교시 · 1학년 3반 교실</p><div class="agenda">이번 안건: 웹 업무 견습 과정 신설</div><div class="quick-actions"><button data-go="help">상담 신청</button><button data-go="meeting">의견 제안</button></div></section></div>`}
function life(){const filter=state.noticeFilter,notices=F.notices.filter(n=>filter==="전체"||n.type===filter);return`${header("학급생활 · 모두 가상 정보","시간표·급식·공지")}<div class="tabbar" role="tablist" aria-label="학급생활 항목"><button class="active">오늘</button><button data-action="meal">급식 상세</button><button data-action="calendar">학급달력</button><button data-action="cleaning">청소·역할</button></div><div class="content-grid"><section class="card wide"><div class="section-heading"><div><span class="kicker blue">가상 시간표</span><h2>오늘 수업</h2></div><span class="soft-note">9월 14일 월요일</span></div><div class="timetable">${F.schedule.map(s=>`<div class="period ${s.period===5?"current":""}"><span>${s.period}교시</span><strong>${s.subject}</strong><small>${s.time} · ${s.room}</small></div>`).join("")}</div></section><section class="card"><span class="kicker orange">발표용 예시 식단</span><h2>오늘의 급식</h2><p class="menu-text">${F.meal.menu.join(" · ")}</p><p class="fine">알레르기 번호 예시 ${F.meal.allergy}<br>갱신 ${F.meal.updated} · 출처 자리표시: 학교 공식 공개자료</p><button class="secondary" data-action="meal">알림 다시 보기</button></section><section class="card"><span class="kicker green">공동 시민의무</span><h2>오늘 청소 · 교실 바닥</h2><p>같은 구역이 2주 연속으로 배정되지 않도록 피하고, 필요한 청소 구역 조정은 사유를 공개하지 않고 제공합니다.</p><div class="info-row"><span>담당</span><strong>6명</strong></div><div class="info-row"><span>교대</span><strong>9월 21일</strong></div><button class="secondary" data-action="cleaning">도움 요청</button></section><section class="card wide"><div class="section-heading"><div><span class="kicker violet">가상 공지</span><h2>공지와 준비물</h2></div><div class="filters">${["전체","중요","학급","과제"].map(x=>`<button class="${filter===x?"active":""}" data-filter="${x}">${x}</button>`).join("")}</div></div><div class="list">${notices.map(n=>`<button class="list-row" data-notice-title="${n.title}"><span class="type-badge">${n.type}</span><span><strong>${n.title}</strong><small>${n.date} · ${n.author}</small></span><span aria-hidden="true">›</span></button>`).join("")}</div></section><section class="card wide"><div class="section-heading"><div><span class="kicker rose">가까운 일정</span><h2>학급달력</h2></div><small>실제 학교 일정이 아닌 예시</small></div><div class="event-list">${F.events.map(e=>`<button data-event="${e.title}"><span class="calendar-date">${e.date}</span><span><strong>${e.title}</strong><small>${e.meta}</small></span><span class="d-day">${e.dday}</span></button>`).join("")}</div></section><section class="card"><span class="kicker navy">준비물 체크</span><h2>내 체크리스트</h2>${["체육복","통합과학 보안경","영어 말하기 개요"].map((t,i)=>`<label class="check-row"><input type="checkbox" data-task="${i}" ${state.tasks.includes(i)?"checked":""}><span>${t}</span></label>`).join("")}</section></div>`}
function help(){return`${header("상담·도움","혼자 고민하지 마세요, 당신의 이야기에 귀를 기울이겠습니다")}${rights()}<div class="content-grid help-grid"><section class="card wide calm"><span class="kicker green">비공개 경로</span><h2>담임 상담 신청</h2><p>희망 시간과 방식만 골라도 됩니다. 민감한 내용은 웹에 쓰지 않고 직접 말해도 됩니다.</p><button class="primary compact" data-action="counsel">상담 신청하기</button></section><section class="card"><h2>대체 수단</h2><ul class="clean-list"><li>쉬는 시간 담임에게 대면 신청</li><li>같은 형식의 종이 신청서</li></ul><p class="fine">접속 실패나 개인기기 부재로 불이익을 주지 않습니다.</p></section><section class="card"><h2>학생정부는 볼 수 없어요</h2><p>상담 분류·내용·신청 여부는 다른 학생과 학생임원에게 공개되지 않습니다.</p></section><section class="card wide warning"><strong>긴급한 안전·폭력·건강 문제인가요?</strong><p>이 웹폼만 기다리지 말고 즉시 담임선생님께 알려 주세요.</p></section></div>`}
function meeting(){return`${header("학급회의","여러분의 의견이 규칙이 됩니다")}<div class="content-grid"><section class="card wide"><div class="section-heading"><div><span class="kicker blue">9월 16일 · 7교시</span><h2>예정된 학급회의</h2></div><span class="status open">안건 접수 중</span></div><div class="agenda-list"><div><span>01</span><p><strong>웹 업무 견습 과정 신설</strong><small>제도 디버그 데이</small></p></div><div><span>02</span><p><strong>9월 공동프로젝트 제안</strong><small>가용예산 안에서 목적·업무 검토</small></p></div></div><p class="fine"><strong>회의 의장</strong>이 발언기회·학생정부 보고·표결절차 등을 확인하고, <strong>학급 서기</strong>가 결정사항과 재검토일 등을 기록합니다.</p><button class="primary compact" data-action="proposal">안건 제안하기</button></section><section class="card"><span class="kicker violet">학생정부 권한</span><h2>결정할 수 있어요</h2><ul class="clean-list"><li>집계지표로 필요한 일 제안</li><li>가용예산의 우선순위</li><li>시험 가능한 선택정책</li></ul></section><section class="card"><span class="kicker rose">학생정부 권한 밖</span><h2>결정할 수 없어요</h2><ul class="clean-list"><li>사람을 지명해 채용</li><li>기본권과 필요한 지원 표결</li><li>민감사건·상담·처벌 결정</li></ul></section><section class="card wide onbo-card"><div class="onbo-masthead"><div><span class="kicker green">학급언론 · 편집장 책임발행</span><h2>온보 <em>ON:報</em></h2><p>학생정부와 분리되어 우리 반의 결정과 그 영향을 확인하고 기록합니다.</p></div><div class="onbo-issue"><span>제7호</span><strong>2026.09.21</strong></div></div><div class="onbo-grid"><article><span class="onbo-label">사실 확인</span><strong>숙련업무가 일부 경험자에게 반복됐습니다</strong><p>최근 학급 업무기록에서 웹 게시 작업을 맡는 학생이 반복되는 경향을 확인했습니다.</p><small>학급 업무기록 확인 · 온보 편집부</small></article><article><span class="onbo-label voice">다른 목소리</span><strong>업무를 나누면 검수 부담이 늘 수 있어요</strong><p>견습 단계를 만들더라도 기존 담당자의 검수시간이 과도해지지 않도록 살펴야 한다는 의견입니다.</p><small>학생 제보 · 신원 비공개</small></article><article><span class="onbo-label reply">공식 답변</span><strong>4주간의 견습 시스템을 시험하겠습니다</strong><p>학생정부는 시험안을 학급회의에 올리고, 종료 뒤 참여기회와 검수시간을 함께 공개하기로 했습니다.</p><small>학생정부 답변 · 9월 21일</small></article></div><div class="onbo-footer"><p><strong>온보 원칙</strong> 편집장이 온보를 책임지고 관리합니다. 추가 업무가 필요할 때, 편집부원을 공개채용합니다.</p><button class="secondary" data-action="opinion">온보 편집부에 제보하기</button></div><p class="fine">제보자의 신원을 함부로 공개하지 않으며, 개인을 알아볼 수 있는 내용은 기사에 싣지 않습니다.</p></section></div>`}
function classon(){const m=money();return`${header("CLASS:ON · 운영도구","일·선택·예산의 흐름")}${rights()}<div class="hub-grid"><button class="hub-card featured-hub" data-go="jobs"><span class="kicker navy">이번 주</span><strong>일·공개채용</strong><p>실제 필요한 일만 공개하고 지원합니다.</p><span class="linkish">${state.applied?"웹 게시 작업 · "+(state.result?"지급 완료":"지원 완료"):"모집 중 2건"} →</span></button><button class="hub-card" data-go="wallet"><span class="kicker blue">개인 비공개</span><strong>지갑·거래내역</strong><p>잔액과 임금은 본인에게만 보입니다.</p><span class="linkish">${fmt(m.balance)} ON →</span></button><button class="hub-card" data-go="activities"><span class="kicker orange">선택활동</span><strong>신청곡·공동프로젝트·투자</strong><p>권리가 아닌 선택활동만 ON으로 구매하여 참여할 수 있습니다.</p><span class="linkish">이번 주 현황 →</span></button><button class="hub-card" data-go="seating"><span class="kicker green">필요 먼저</span><strong>순환 자리배치</strong><p>필요좌석을 보장한 뒤 희망구역을 제출합니다.</p><span class="linkish">희망구역 선택 →</span></button><button class="hub-card" data-go="budget"><span class="kicker violet">공개 가용예산</span><strong>학생정부 예산</strong><p>승인·집행·잔액을 한눈에 확인합니다.</p><span class="linkish">집행내역 →</span></button><button class="hub-card debug-hub" data-go="debug"><span class="kicker rose">4주 결산</span><strong>제도 디버그 데이</strong><p>실패한 규칙을 숨기지 않고 함께 고칩니다.</p><span class="version-chip">CLASS:ON ${state.version}</span></button></div><section class="boundary-note"><strong>ON이 하지 않는 것</strong><span>현금교환 · 학생 간 송금·대출 · 사적고용 · 성적·친절·준법 보상 · 기본권 구매</span></section>`}
function jobs(){return`${header("CLASS:ON · 일·공개채용","이번 주 공개채용",`<span class="status large open">모집 중 2건</span>`)}${crumb("9월 21일 기준")}<section class="jobs-board" aria-label="공개채용 공고"><button class="job-listing featured-listing" data-go="job"><div class="job-list-top"><span class="kicker navy">숙련업무</span><span class="status ${state.applied?"done":"open"}">${state.result?"지급 완료":state.applied?"지원 완료":"모집 중"}</span></div><h2>웹 게시 작업</h2><p>승인된 학급회의 결과를 HTML·CSS·JS를 활용하여 학생정부 웹페이지에 게시</p><dl><div><dt>예상시간</dt><dd>35~45분</dd></div><div><dt>세전임금</dt><dd>12 ON</dd></div><div><dt>마감</dt><dd>9월 21일 16:00</dd></div></dl><span class="listing-link">공고 보기 →</span></button><article class="job-listing static-listing" aria-label="학급 접근성 지원 공고"><div class="job-list-top"><span class="kicker green">일반업무</span><span class="status open">모집 중</span></div><h2>학급 접근성 지원</h2><p>교실 통로와 공용 기자재 배치를 확인하고, 개인정보 없는 참여환경 점검표를 작성합니다.</p><dl><div><dt>예상시간</dt><dd>20~30분</dd></div><div><dt>세전임금</dt><dd>8 ON</dd></div><div><dt>결과물</dt><dd>환경 점검표</dd></div></dl><span class="listing-note">공고 확인만 가능</span></article></section><p class="jobs-footnote">한 학생은 한 달에 업무 하나만 맡을 수 있습니다. 필요한 개인지원은 채용과 무관하게 학교가 먼저 보장합니다.</p>`}
function job(){const status=state.result?"업무 완료·지급 완료":state.applied?"지원 완료":"모집 중";return`${header("CLASS:ON · 일·공개채용","웹 게시 작업",`<span class="status large ${state.applied?"done":"open"}">${status}</span>`)}<div class="crumb"><a class="back-link" href="#jobs">← 공개채용 목록</a><p class="page-kicker">숙련업무 · 모집 중</p></div><div class="job-detail-grid"><section class="card job-main"><div class="reason-block"><span>왜 필요한가요?</span><strong>학급회의 결과를 학생·보호자가 읽기 쉬운 공개 페이지로 정리할 필요가 있습니다.</strong></div><h2>할 일</h2><ol class="task-list"><li><span>1</span>승인된 학급회의 결과 3건을 HTML·CSS·JS를 활용하여 학생정부 웹페이지에 게시</li><li><span>2</span>모바일 화면 가독성 및 내부 링크 정상 작동 여부 점검</li><li><span>3</span>개인정보 포함 여부를 직무 체크리스트로 최종 점검</li></ol><div class="spec-grid"><div><span>예상시간</span><strong>35~45분</strong></div><div><span>세전임금</span><strong>12 ON</strong></div><div><span>결과물</span><strong>게시 URL·점검표</strong></div><div><span>지원 마감</span><strong>9월 21일 16:00</strong></div></div><div class="qual"><strong>최소 자격 요건</strong><p>직접 구현한 웹 포트폴리오 1페이지 제출 또는 공개 체크리스트 통과<br>최종 결과는 타인에게 공개되지 않으며, 본인에게만 '통과' 또는 '보완 필요' 형태로 개별 안내됩니다.</p></div></section><aside class="card action-card"><span class="kicker blue">선발 원칙</span><h2>다양한 기회 제공과 수행 가능성을 최우선으로 고려합니다.</h2><p>최소자격 확인 → 최근 한 달간 노동하지 않은 학생 1순위 우대 → 해당 분야 미경험 학생 2순위 우대 → 동률 비공개 추첨</p><div class="student-gov-limit">학생정부는 새로운 업무를 제안할 수 있지만 사람을 직접 지명하지 못합니다.</div>${state.applied?`<div class="success-state"><span aria-hidden="true">✓</span><strong>${status}</strong><p>${state.result?"결과물 확인과 담임 지급승인이 완료되었습니다.":"지원서가 접수되었습니다. 결과는 내 알림으로 안내됩니다."}</p></div>`:""}<button class="primary" data-action="apply" ${state.applied?"disabled":""}>${state.applied?"지원 완료":"지원하기"}</button>${state.result?`<button class="secondary strong" data-go="wallet">지갑·거래내역 보기 →</button>`:""}<p class="fine">결과물 확인 후 담임 승인 시 임금이 지급됩니다.</p></aside></div>`}
function wallet(){const m=money();return`${header("CLASS:ON · 개인 비공개","지갑·거래내역",`<div class="profile privacy"><span class="avatar">김</span><span><strong>김민준</strong><small>본인에게만 표시</small></span></div>`)}${crumb("내 지갑")}<div class="wallet-layout"><section class="balance-card"><div><span>현재 잔액</span><strong>${fmt(m.balance)} <small>ON</small></strong><p>${F.student.initialBalance} ON으로 학기 시작</p></div><span class="privacy-mark">🔒 개인 비공개</span></section>${state.result?`<section class="card wage-breakdown"><div class="section-heading"><div><span class="kicker blue">지급 승인 완료</span><h2>웹 게시 작업</h2></div><span class="date-block">9월 21일</span></div><div class="wage-flow"><div><span>세전임금</span><strong>12 ON</strong><small>학생정부 계정 지급</small></div><span aria-hidden="true">−</span><div><span>근로세 10%</span><strong>1.2 ON</strong><small>중앙금고로 이동</small></div><span aria-hidden="true">=</span><div class="net"><span>세후입금</span><strong>10.8 ON</strong><small>김민준 지갑</small></div></div><p class="fine">근로세는 지급 시 자동 반영됩니다.</p></section>`:""}<section class="card transaction-card"><div class="section-heading"><div><span class="kicker blue">최근 30일</span><h2>거래내역</h2></div><span class="soft-note">${state.result?"4":"3"}건</span></div>${state.result?`<div class="transaction"><span class="tx-icon plus">+</span><div><strong>웹 게시 작업 세후입금</strong><small>9월 21일 · 학생정부 계정 → 김민준</small></div><strong class="amount plus">+10.8 ON</strong></div>`:""}<div class="transaction"><span class="tx-icon minus">−</span><div><strong>청소시간 신청곡 · 이 별로부터</strong><small>9월 20일 · 김민준 → 학생정부 계정</small></div><strong class="amount minus">−2 ON</strong></div><div class="transaction"><span class="tx-icon minus">−</span><div><strong>9월 CLASS:ON 주민세</strong><small>9월 19일 · 김민준 → 중앙금고</small></div><strong class="amount minus">−1 ON</strong></div><div class="transaction"><span class="tx-icon minus">−</span><div><strong>프로필 배경·배지 프로젝트 참여</strong><small>9월 18일 · 김민준 → 프로젝트 계정</small></div><strong class="amount minus">−3 ON</strong></div></section><section class="tax-note"><strong>주민세는 한 달에 1 ON씩 지불</strong><span>부족액은 이월하지 않습니다. 납부 여부와 관계없이 학급의 권리는 그대로입니다.</span></section><section class="rights-ledger"><strong>잔액이 0이어도</strong><span>빚·체납 없음</span><span>시민권 제한 없음</span><span>노동 미참여 불이익 없음</span><span>상담·필요지원 그대로</span></section></div>`}
function activities(){return`${header("CLASS:ON · 선택활동","이번 주 선택 활동")}${crumb("자율 참여 현황")}${rights()}<div class="activity-layout"><section class="card song-panel"><div class="section-heading"><div><span class="kicker orange">한 곡 2 ON</span><h2>청소시간 신청곡</h2></div><span class="status open">4곡</span></div><p>신청 순서와 학급 운영시간을 함께 고려해 재생합니다.</p><div class="song-queue">${F.songs.map((s,i)=>`<article class="song-row ${i===0?"mine":""}"><span class="song-number">${i+1}</span><div><strong>${s.title}</strong><small>${s.artist} · ${s.student}</small></div><span class="song-status">${s.status}</span></article>`).join("")}</div><button class="secondary" data-action="activity">신청 규칙 보기</button></section><section class="project-panel"><div class="section-heading"><div><span class="kicker violet">학생 기여 + 학생정부 지원</span><h2>진행 중인 공동프로젝트</h2></div><span class="soft-note">목표 미달 시 학생 기여금 전액 환불</span></div><div class="project-list">${F.projects.map((p,i)=>{const funded=p.raised>=p.goal,total=p.raised+p.governmentGrant;return`<article class="card project-card"><div class="project-card-head"><span class="project-icon">${i===0?"✦":"◒"}</span><span class="status ${funded?"done":"open"}">${funded?"모금 완료":"모금 중"}</span></div><h3>${p.title}</h3><p>${p.description}</p><div class="project-progress"><div><span>학생 기여 <strong>${p.raised} ON</strong></span><span>목표 ${p.goal} ON</span></div><div class="progress-track"><span style="width:${Math.min(100,Math.round(p.raised/p.goal*100))}%"></span></div></div>${p.governmentGrant?`<div class="funding-split"><span>학생 기여 <strong>${p.raised} ON</strong></span><b>＋</b><span>학생정부 지원 <strong>${p.governmentGrant} ON</strong></span><b>＝</b><span class="funding-total">집행예산 <strong>${total} ON</strong></span></div>`:""}<div class="project-meta"><span>참여 ${p.supporters}명</span><span>${funded?"마감":"마감 예정"} ${p.due}</span>${p.myContribution?`<span>내 참여 ${p.myContribution} ON</span>`:""}</div><button class="secondary" data-action="project">운영내역 보기</button></article>`}).join("")}</div></section><section class="card activity-flow"><h2>공동프로젝트 예산은 어떻게 만들어지나요?</h2><div class="flowline"><span>학생 자율기여</span><b>＋</b><span>학생정부 지원금</span><b>→</b><span>프로젝트 계정</span><b>→</b><span>승인된 노동·재료</span></div><p class="fine">학생 기여가 목표에 도달한 뒤 학생정부 지원금을 합쳐 집행합니다. 미사용 지원금은 중앙금고로, 미사용 학생 기여금은 참여 학생에게 돌아갑니다.</p></section></div>`}
function seating(){const zones=["앞·창가","앞·복도","가운데·창가","가운데·복도","뒤·창가","뒤·복도"],opts=(value)=>`<option value="">구역을 선택해 주세요</option>${zones.map(z=>`<option ${value===z?"selected":""}>${z}</option>`).join("")}`,bidOpts=`<option value="">입찰액 선택</option>${[1,2,3,4,5,6,7,8].map(n=>`<option value="${n}" ${String(n)===state.auctionBid?"selected":""}>${n} ON</option>`).join("")}`,m=money();return`${header("CLASS:ON · 자리배치","다음 자리 희망구역 선택")}${crumb("9월 29일 마감 · 약 4주마다 재배치")}<section class="auction-panel"><div class="auction-copy"><div class="auction-heading"><span class="kicker violet">9월 EXPANSION · 입찰 접수 중</span><span class="status open">선택순서 3장</span></div><h2>남은 좌석 선택순서 제한경매</h2><p>필요좌석을 먼저 배정한 뒤 남은 좌석을 고르는 <strong>순서</strong>만 경매합니다. 좌석 자체를 사는 것이 아니며, 입찰하지 않아도 모든 학생이 아래에서 희망구역을 제출할 수 있습니다.</p><ul><li>학생당 1건 · 상한 8 ON · 낙찰자만 입찰액 납부</li><li>입찰액순으로 1·2·3순위 결정 · 동액은 비공개 추첨</li><li>직전 달 낙찰자는 제외 · 학기 최대 2회</li></ul></div><div class="auction-form"><span class="auction-balance">현재 잔액 <strong>${fmt(m.balance)} ON</strong></span><label>비공개 입찰액<select id="auction-bid">${bidOpts}</select></label><button class="primary" data-action="save-bid">${state.auctionBid?"입찰액 수정":"비공개 입찰 제출"}</button>${state.auctionBid?`<p class="bid-saved"><span>✓</span><strong>${state.auctionBid} ON 입찰 저장됨</strong><small>낙찰될 때만 차감됩니다.</small></p>`:`<p class="fine">다른 학생은 입찰 여부와 금액을 볼 수 없습니다.</p>`}</div></section><section class="seat-intro"><span class="status">권리 우선</span><h2>필요한 자리는 먼저 보장합니다</h2><p>시력·청력·건강·집중 등 필요한 자리는 ON이나 경매·추첨과 무관하게 담임이 먼저 반영합니다.</p></section><div class="seat-choice-layout"><section class="card zone-card"><div class="classroom-front">칠판 · 교탁</div><div class="zone-map" aria-label="교실 희망구역 안내">${zones.map(z=>`<span class="${state.seatFirst===z?"first":state.seatSecond===z?"second":""}">${z}<small>${state.seatFirst===z?"1순위":state.seatSecond===z?"2순위":""}</small></span>`).join("")}</div><div class="zone-legend"><span><i class="first"></i>1순위</span><span><i class="second"></i>2순위</span></div></section><section class="card seat-form-card"><span class="kicker green">김민준 · 개인 화면</span><h2>희망구역 제출</h2><label>1순위<select id="seat-first">${opts(state.seatFirst)}</select></label><label>2순위<select id="seat-second">${opts(state.seatSecond)}</select></label><button class="primary" data-action="save-seat">${state.seatFirst?"희망구역 수정":"희망구역 저장"}</button><p class="fine">초과 구역은 비공개 추첨하며, 다른 학생에게 선택 내용과 조정 사유를 공개하지 않습니다.</p></section></div><div class="seat-process"><article><span>1</span><strong>필요좌석 선보장</strong><small>담임이 비공개 반영</small></article><article><span>2</span><strong>선택순서 3장 경매</strong><small>선택 사항</small></article><article><span>3</span><strong>희망구역 배정</strong><small>초과 시 비공개 추첨</small></article><article><span>4</span><strong>담임 최소 조정</strong><small>교육적 필요에 의해 일부 반영</small></article></div><div class="center-actions"><button class="secondary" data-go="help">비공개 상담·이의 제기</button></div>`}
function budget(){const used=F.budget.reduce((sum,x)=>sum+x.amount,0),remaining=150-used;return`${header("CLASS:ON · 학생정부","9월 가용예산 집행현황")}${crumb("9월 21일 09:30 갱신")}<section class="rights-banner"><span class="rights-icon">✓</span><div><strong>기본권과 필요한 지원은 예산경쟁 밖</strong><p>가용예산이 0이어도 교육·상담·필요좌석·합리적 지원은 담임과 학교가 먼저 보장합니다.</p></div></section><div class="budget-overview"><article><span>이번 달 가용한도</span><strong>150 ON</strong><small>의무지출 목표가 아닌 상한</small></article><article><span>승인·배정</span><strong>${used} ON</strong><small>집행 중·예정 포함</small></article><article class="remaining"><span>남은 가용액</span><strong>${remaining} ON</strong><small>추가 안건 또는 다음 달</small></article><article class="reserve-summary"><span>별도 안전준비선</span><strong>156 ON</strong><small>상시직 136 + 최소기회 20</small></article></div><section class="card budget-ledger"><div class="section-heading"><div><span class="kicker violet">학생정부 계정</span><h2>승인·집행내역</h2></div><span class="status done">합계 ${used} ON</span></div><div class="budget-table"><div class="budget-row budget-head"><span>사업·업무</span><span>세부내역</span><span>상태</span><strong>금액</strong></div>${F.budget.map(x=>`<div class="budget-row"><span><strong>${x.title}</strong></span><span>${x.detail}</span><span><i class="budget-status">${x.status}</i></span><strong>${x.amount} ON</strong></div>`).join("")}</div><p class="fine">실물 구매가 필요한 항목은 학교 회계·구매 절차 승인을 거친 뒤 집행합니다.</p></section><section class="card budget-principles"><h2>집행 원칙</h2><div><span>01</span><p><strong>필요성과 공공성 확인</strong><small>실제 필요한 업무와 활동만 편성</small></p></div><div><span>02</span><p><strong>업무 승인</strong><small>채용은 공개 절차로 별도 진행</small></p></div><div><span>03</span><p><strong>노동·재료·잔액 공개</strong><small>개인의 민감정보는 공개하지 않음</small></p></div></section><section class="card budget-policy"><div class="section-heading"><div><span class="kicker violet">정책기록</span><h2>견습 경로 시험안</h2></div><span class="version-chip">CLASS:ON ${state.version}</span></div><div class="policy-flow">${["제안","예상","시험 시행","실제 결과","영향 확인","수정 또는 종료"].map((x,i)=>`<span class="${state.version==="1.1"&&i<3?"active":""}">${x}</span>`).join("<b>→</b>")}</div><button class="secondary" data-go="debug">제도 디버그에서 보기 →</button></section>`}
function debug(){const picked=state.debugChoice,enacted=state.version==="1.1";return`${header("제도 디버그 데이","실패한 규칙을 함께 고칩니다",`<div class="version-display"><span>현재 버전</span><strong>CLASS:ON ${state.version}</strong></div>`)}${crumb("4주 결산 · 가상 익명 집계")}<section class="debug-hero"><div><span class="kicker rose">문제 발견</span><h2>웹 숙련업무가<br>소수 경험자에게 반복 의존</h2><p>지원자 개인이 아니라 업무범위와 학습경로를 고칠 문제로 봅니다.</p></div><div class="evidence-card"><span>익명 집계</span><strong>숙련 미충원 경보</strong><div><span>반복 의존</span><b>확인</b></div><div><span>영향 경험</span><b>비공개 확인</b></div><small>가상 데이터. 실제 26명 학급에서는 3명 이상이어도 재식별 가능하면 공개하지 않습니다.</small></div></section>${enacted?`<section class="version-success"><span class="spark" aria-hidden="true">✓</span><div><span>시험정책 기록 완료</span><h2>CLASS:ON 1.0 <b>→</b> 1.1</h2><p>성공을 확정한 것이 아닙니다. 실제 결과와 영향을 받은 학생의 경험은 다음 결산에서 확인합니다.</p></div></section><div class="trial-grid"><section><span>시험정책</span><strong>책임 작업자 + 견습 경로</strong><small>독립 결과물·약 절반 업무와 임금</small></section><section><span>시험기간</span><strong>9월 21일 → 10월 16일</strong><small>종료일 자동 기록</small></section><section><span>다음 4주 결산</span><strong>10월 19일</strong><small>유지·수정·종료 판단</small></section></div><div class="rights-banner compact-banner"><span class="rights-icon">✓</span><div><strong>기본권·안전은 시험대상이 아닙니다</strong><p>선택정책만 종료일과 중단선을 두고 시험합니다.</p></div></div>`:`<section class="choice-section"><div class="section-heading"><div><span class="kicker blue">학생들이 토론할 시험안</span><h2>어떤 규칙을 먼저 시험할까요?</h2></div><small></small></div><div class="choice-grid"><button class="choice ${picked==="apprentice"?"selected":""}" data-choice="apprentice"><span class="choice-check">${picked==="apprentice"?"✓":"1"}</span><div><h3>견습 경로 추가</h3><p>책임 작업자와 독립 결과물이 있는 견습을 함께 공고합니다.</p><dl><div><dt>기대효과</dt><dd>다음 자격경험 확산</dd></div><div><dt>위험</dt><dd>검수·교사시간 증가</dd></div><div><dt>시험기간</dt><dd>4주</dd></div></dl></div></button><button class="choice ${picked==="split"?"selected":""}" data-choice="split"><span class="choice-check">${picked==="split"?"✓":"2"}</span><div><h3>업무를 더 작게 나누기</h3><p>독립 산출물이 있는 경우에만 업무범위를 분할합니다.</p><dl><div><dt>기대효과</dt><dd>진입장벽 완화</dd></div><div><dt>위험</dt><dd>쪼개기·연결오류</dd></div><div><dt>시험기간</dt><dd>4주</dd></div></dl></div></button></div><button class="primary enact" data-action="enact" ${picked!=="apprentice"?"disabled":""}>견습 경로 시험 시행 <span aria-hidden="true">→</span></button><p class="fine center">오늘의 가상 시나리오 선택은 ‘견습 경로 추가’입니다. 결과는 아직 확인되지 않았습니다.</p></section>`}`}
function guide(){return`${header("규칙·안내","권리가 제도보다 먼저입니다")}${rights()}<div class="content-grid"><section class="card wide"><span class="kicker navy">권리헌장</span><h2>우리 반의 다섯 약속</h2><ol class="promise-list"><li>서로의 기본권을 침해하지 않습니다.</li><li>개인정보와 사적인 사정을 함부로 공개하지 않습니다.</li><li>청소·공용물품·학급회의의 공동책임을 함께 나눕니다.</li><li>의견이 달라도 모욕하거나 강요하지 않습니다.</li><li>불편한 규칙은 제안하고 함께 고칩니다.</li></ol></section><section class="card"><h2>공개되는 정보</h2><p>예산·정책 등</p></section><section class="card"><h2>비공개 정보</h2><p>잔액·거래·임금·건강·장애·상담·가정·생활지도 등</p></section><section class="card"><h2>접근성·대체경로</h2><p>특수교육 대상학생의 유무에 따라 큰 글씨·스크린 리더 등을 추가로 지원할 예정이며, 대면 종이 제출이 웹 작업과 같은 효력을 가집니다.</p></section><section class="card"><h2>시스템 범위</h2><p>CLASS:ON v1.2 FINAL · 발표용 프런트엔드. 실제 인증·DB·개인정보 처리는 구현하지 않았습니다.</p></section><section class="card wide minimal"><div><span class="kicker rose">최소모드</span><h2>학급 상황과 교사의 운영 소요에 따라 시스템 기능을 유연하게 축소하여 운영합니다.</h2><p>학생의 기본 권리, 시민 의무, 확정된 급여 지급, 세금 오류 정정, 기존 발생 의무, 기본 접근 지원은 변함없이 유지됩니다. 신규 프로젝트, 경매, 투자, 가격 변경 등 추가적인 경제 활동은 일시 동결됩니다.</p></div><button class="secondary" data-action="minimal">최소모드 안내 보기</button></section></div>`}
function backup(){const scenes=[["김민준 홈","home"],["웹 게시 작업 상세","job"],["지원 완료","job-applied"],["지갑·거래내역","wallet"],["제도 디버그 1.0","debug"],["견습 경로 선택","debug-picked"],["CLASS:ON 1.1","debug-11"]];return`${header("발표자용 복구","백업 장면 바로가기",`<button class="secondary" data-demo="reset">전체 초기화</button>`)}<section class="backup-note"><strong>라이브가 멈추면 5초 안에 이 화면으로</strong><p>각 버튼은 같은 최종 빌드의 결정적 상태를 재현합니다. 실제 자동선발이나 정책효과를 뜻하지 않습니다.</p></section><div class="backup-grid">${scenes.map((s,i)=>`<button data-backup="${s[1]}"><span>${String(i+1).padStart(2,"0")}</span><strong>${s[0]}</strong><small>백업 상태 열기 →</small></button>`).join("")}</div><div class="backup-summary"><div><span>시연 1</span><strong>홈 → 공고 → 지원 → 다음 상태·지갑</strong><small>화면 안 3회 클릭</small></div><div><span>시연 2</span><strong>디버그 → 견습 선택 → 시험 시행</strong><small>화면 안 2회 클릭</small></div></div>`}
function polishRealism(root=main){const replacements=[["일반계 고1 · 26명 가상학급","한민고등학교 · 1학년 13반"],["좋은 오후예요, 김민준님","좋은 아침이에요, 김민준님"],["가상학생","1학년 13반"],["2026년 9월 14일 월요일","2026년 9월 21일 월요일"],["다음 수업","현재 수업"],["5교시 · 통합사회","2교시 · 수학"],["13:40","10:00–10:50"],["1학년 3반 교실 · 작은 사회의 규칙","1학년 13반 교실 · 이차방정식"],["6교시 체육","3교시 영어"],["체육복 준비","어학실 이동"],["가상 급식 정보","한민고 급식"],["알레르기 예시 1·3·5·6·13 · 발표용 식단","한민고등학교 · 9월 21일 중식"],["오늘 08:10 · 담임 · 가상 공지","오늘 08:10 · 담임"],["15:40","16:10"],["9월 16일 수요일 · 7교시 · 1학년 3반 교실","9월 23일 수요일 · 7교시 · 1학년 13반 교실"],["학급생활 · 모두 가상 정보","학급생활"],["가상 시간표","오늘 시간표"],["9월 14일 월요일","9월 21일 월요일"],["발표용 예시 식단","한민고 오늘 급식"],["알레르기 번호 예시 1·3·5·6·13","9월 21일 중식"],["갱신 2026.09.14 08:00 · 출처 자리표시: 학교 공식 공개자료","한민고등학교 급식표 · 08:00 갱신"],["교대 9월 21일","교대 9월 28일"],["가상 공지","학급 공지"],["실제 학교 일정이 아닌 예시","1학년 13반 일정"],["실제 학교 일정이 아닌 발표용 예시입니다.","학급 일정은 담임 승인 후 반영됩니다."],["숙련업무 · 발표용 공고","숙련업무 · 모집 중"],["결과물 확인과 담임 지급승인을 재현한 가상 상태입니다.","결과물 확인과 담임 지급승인이 완료되었습니다."],["실제 운영에는 최소자격 확인·결과물 확인·담임 지급승인이 별도로 필요합니다.","결과물 확인 후 담임 승인 시 임금이 지급됩니다."],["가상학생 개인 화면","내 지갑"],["지급 승인 완료 · 가상 상태","지급 승인 완료"],["사이트는 계산과 기록을 돕고, 결과 확인과 지급승인은 담임의 책임입니다.","근로세는 지급 시 자동 반영됩니다."],["4주 결산 · 가상 익명 집계","4주 결산 · 익명 집계"],["가상 데이터. 실제 26명 학급에서는 3명 이상이어도 재식별 가능하면 공개하지 않습니다.","개인 식별 가능성이 있는 소규모 집계는 공개하지 않습니다."],["오늘의 가상 시나리오 선택은 ‘견습 경로 추가’입니다.","선택한 안은 ‘견습 경로 추가’입니다."],["가상 신청:","신청 내용:"],["예시 공고입니다.","공고입니다."],["오늘의 급식 · 가상 정보","오늘의 급식"],["실제 운영 시 학교 공식 API 또는 공개 홈페이지 자료를 사용합니다. 학생 입력이나 건강정보 추론 기능은 없습니다.","한민고등학교 급식표 기준 · 9월 21일 중식"],["발표용 접수 완료","상담 신청"],["발표용 상담 신청이 접수되었습니다. 실제 전송은 없습니다.","상담 신청이 접수되었습니다."],["발표자료 공동 점검 시간을 만들어요","교실 환경 공동 점검 시간을 만들어요"],["발표용 제안 접수","제안 보내기"],["가상 제안이 접수되었습니다.","제안이 접수되었습니다."]];const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){for(const [from,to] of replacements)node.nodeValue=node.nodeValue.replaceAll(from,to);node.nodeValue=node.nodeValue.replaceAll("발표용 ","").replaceAll("가상 ","").replaceAll("가상","")}root.querySelectorAll?.(".period").forEach((el,i)=>el.classList.toggle("current",i===1));const next=root.querySelector?.(".present-next");if(next)next.textContent="결과 확인 이후 상태 보기 →";root.querySelectorAll?.(".card h2").forEach(h=>{if(h.textContent.trim()==="시스템 범위")h.closest(".card")?.remove()})}
function polishSchoolData(root=main){const extra=[["9월 16일 수요일 · 7교시 · 1학년 3반 교실","9월 21일 월요일 · 7교시 · 1학년 13반 교실"],["9월 16일 · 7교시","9월 21일 · 7교시"],["9월 16일 · 프로젝트 계정 → 김민준","9월 23일 · 프로젝트 계정 → 김민준"],["9월 17일 · 김민준 → 학생정부 계정","9월 24일 · 김민준 → 학생정부 계정"]];const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode())for(const [from,to] of extra)node.nodeValue=node.nodeValue.replaceAll(from,to);const lunch=root.querySelector?.(".lunch-card");if(lunch){const menu=lunch.querySelector(".menu-text");if(menu)menu.textContent="현미보리밥 · 한우소머리장터국 · 두부양념구이 외 4종";const meta=lunch.querySelector("small");if(meta)meta.textContent="한민고등학교 · 9월 21일 중식"}root.querySelectorAll?.(".kicker.orange").forEach(kicker=>{if(kicker.textContent.trim()==="한민고 오늘 급식"){const fine=kicker.closest(".card")?.querySelector(".fine");if(fine)fine.innerHTML="한민고등학교 급식표<br>9월 21일 중식 · 08:00 갱신"}});root.querySelectorAll?.(".info-row").forEach(row=>{if(row.querySelector("span")?.textContent.trim()==="교대")row.querySelector("strong").textContent="9월 28일"});root.querySelectorAll?.(".date-block").forEach(el=>el.textContent="9월 23일");root.querySelectorAll?.(".d-day").forEach(el=>{if(el.textContent.trim()==="D-2"&&el.closest(".upcoming-card"))el.textContent="D-DAY"});root.querySelectorAll?.(".timetable .period").forEach((period,i)=>{const meta=period.querySelector("small");if(meta&&F.schedule[i])meta.textContent=`${F.schedule[i].time} · ${F.schedule[i].room} · ${F.schedule[i].teacher}`;period.classList.toggle("current",i===1)});const deadline=[...root.querySelectorAll?.(".spec-grid div")||[]].find(el=>el.querySelector("span")?.textContent.trim()==="지원 마감");if(deadline)deadline.querySelector("strong").textContent="9월 22일 16:00"}
function polishUpcoming(root=main){const card=root.querySelector?.(".upcoming-card");if(!card)return;const detail=card.querySelector("p");if(detail)detail.textContent="9월 21일 월요일 · 7교시 · 1학년 13반 교실";const dday=card.querySelector(".d-day");if(dday)dday.textContent="D-DAY"}
function polishDaySchedule(root=main){const homeSchedule=root.querySelector?.(".schedule-card");if(homeSchedule){homeSchedule.querySelector(".kicker").textContent="현재 수업";homeSchedule.querySelector("h3").textContent="3교시 · 정보";homeSchedule.querySelector(".time-pill").textContent="10:10–11:00";homeSchedule.querySelector("p").textContent="AI라운지 · 구현호";const next=homeSchedule.querySelectorAll(".mini-list span");if(next[0])next[0].textContent="4교시 과학탐구실험2";if(next[1])next[1].textContent="박지우 · 물리실험실 이동"}const homeNotice=root.querySelector?.(".notice-card");if(homeNotice){homeNotice.querySelector("h3").textContent="과학탐구실험2 준비물";homeNotice.querySelector("p").textContent="오늘 과학탐구실험2 수행평가에 사용할 실험복과 필기도구를 준비해 주세요."}const duty=root.querySelector?.(".duty-card .time-pill");if(duty)duty.textContent="16:00–16:10";const upcoming=root.querySelector?.(".upcoming-card p");if(upcoming)upcoming.textContent="9월 21일 월요일 · 창의적 체험활동 · 1학년 13반 교실";root.querySelectorAll?.(".timetable .period").forEach((period,i)=>period.classList.toggle("current",i===2));const timetable=root.querySelector?.(".timetable");if(timetable&&!root.querySelector?.(".day-bands")){timetable.insertAdjacentHTML("afterend",`<div class="day-bands"><span><b>점심시간</b>12:00–13:00</span><span><b>종례·학급청소</b>15:50–16:10</span></div>`)}const cleaning=[...root.querySelectorAll?.(".card h2")||[]].find(h=>h.textContent.includes("오늘 청소"))?.closest(".card");if(cleaning&&!cleaning.querySelector("[data-day-time]"))cleaning.querySelector(".info-row")?.insertAdjacentHTML("beforebegin",`<div class="info-row" data-day-time><span>시간</span><strong>16:00–16:10</strong></div>`);const checklist=root.querySelectorAll?.(".check-row span");["과학탐구실험2 실험복·필기도구","공통영어2 말하기 수행평가 개요 작성","창의적 체험활동 회의자료 준비"].forEach((text,i)=>{if(checklist?.[i])checklist[i].textContent=text});const agenda=root.querySelector?.(".agenda-list")?.closest(".card");if(agenda){const date=agenda.querySelector(".kicker.blue");if(date)date.textContent="9월 21일 · 창의적 체험활동"}root.querySelectorAll?.(".kicker").forEach(kicker=>{if(kicker.textContent.trim()==="시연 핵심")kicker.textContent=kicker.classList.contains("rose")?"4주 결산":"공개채용"});const eyebrow=root.querySelector?.(".eyebrow");if(eyebrow?.textContent.trim()==="CLASS:ON · 운영도구")eyebrow.textContent="CLASS:ON · 학급경제"}
function addCommunityMarket(root=document){const layout=root.matches?.(".activity-layout")?root:root.querySelector?.(".activity-layout");if(!layout||layout.querySelector("#community-market"))return;const flow=layout.querySelector(".activity-flow"),market=document.createElement("section");market.className="card community-market";market.id="community-market";market.innerHTML=`<div class="market-head"><div><span class="kicker blue">2학기 1차 거래 · 주문 접수 중</span><h2>공동체 지수시장</h2><p>우리 반의 공동프로젝트와 참여 과정이 얼마나 잘 운영되는지, 이름 없이 모은 기록으로 지수를 만들어요.</p></div><div class="market-balance"><span>투자 가능 잔액</span><strong>${state.result?"19.8":"9"} ON</strong><small>총 보유 한도 25 ON</small></div></div><div class="market-grid"><article class="index-card up"><div class="index-top"><span class="index-mark">공</span><span class="status open">이번 주 +1.8%</span></div><h3>공동프로젝트 지수</h3><strong class="index-value">104.2</strong><p>프로젝트 목표 달성, 일정 공개, 결산 완료 기록을 모아 계산합니다.</p><div class="mini-chart" aria-label="최근 4주 상승 흐름"><i style="height:34%"></i><i style="height:45%"></i><i style="height:62%"></i><i style="height:78%"></i></div></article><article class="index-card down"><div class="index-top"><span class="index-mark">참</span><span class="status">이번 주 −0.7%</span></div><h3>참여절차 지수</h3><strong class="index-value">98.6</strong><p>회의 안내, 의견 수렴, 결과 공개가 제때 이루어졌는지 확인합니다.</p><div class="mini-chart" aria-label="최근 4주 소폭 하락 흐름"><i style="height:72%"></i><i style="height:65%"></i><i style="height:68%"></i><i style="height:54%"></i></div></article><form class="market-order" id="market-order"><div><span class="order-label">이번 주 주문</span><h3>투자 연습하기</h3><p>고른 금액은 미리보기에서만 확인되며 데모 잔액에서는 빠지지 않습니다.</p></div><label>투자할 지수<select id="market-index"><option value="공동프로젝트 지수">공동프로젝트 지수 · 104.2</option><option value="참여절차 지수">참여절차 지수 · 98.6</option></select></label><label>투자할 금액<select id="market-amount"><option value="1">1 ON</option><option value="3" selected>3 ON</option><option value="5">5 ON</option><option value="8">8 ON</option></select></label><button class="primary" type="submit">주문 미리보기</button><small>주문과 보유내역은 본인에게만 보입니다.</small></form></div><div class="market-rules"><span><b>주 1회</b> 같은 가격으로 체결</span><span><b>±3%</b> 한 주 변동 제한</span><span><b>1%</b> 주문 수수료</span><span><b>±12%</b> 4주 손익 제한</span></div><p class="market-safety"><strong>누군가를 평가하는 점수가 아니에요.</strong> 개인의 성적·행동·행복도는 지수에 넣지 않으며, 특정 학생에게 지수 변동의 책임을 묻지 않습니다.</p>`;market.querySelector("form").addEventListener("submit",event=>{event.preventDefault();const index=market.querySelector("#market-index").value,amount=market.querySelector("#market-amount").value,fee=(Number(amount)*.01).toFixed(2);showInfo("주문 미리보기",`<p><strong>${index}</strong>에 <strong>${amount} ON</strong>을 투자합니다.</p><div class="market-preview"><span>투자금 <strong>${amount} ON</strong></span><span>수수료 <strong>${fee} ON</strong></span><span>다음 체결 <strong>9월 25일</strong></span></div><p class="fine">이 화면은 시연용이라 주문이 저장되거나 ON이 차감되지 않습니다. 실제 운영에서는 확인 버튼을 누른 뒤 주 1회 같은 가격으로 체결합니다.</p>`)});flow?flow.before(market):layout.append(market)}
function polishCommunityMarket(root=document){const market=root.matches?.("#community-market")?root:root.querySelector?.("#community-market");if(!market)return;const cards=market.querySelectorAll(".index-card"),first=cards[0],option=market.querySelector("#market-index option:first-child");market.querySelector(".market-head p").textContent="우리 반의 교실 환경과 참여 과정이 얼마나 잘 운영되는지, 이름 없이 모은 기록으로 지수를 만들어요.";first.querySelector(".index-mark").textContent="환";first.querySelector(".status").textContent="이번 주 +1.3%";first.querySelector("h3").textContent="학급 환경 지수";first.querySelector(".index-value").textContent="103.1";first.querySelector("p").textContent="이동수업 전 전등·냉난방·창문을 확인하고, 쉬는 시간에 환기했는지 모아 계산합니다.";first.querySelector(".mini-chart").setAttribute("aria-label","최근 4주 학급 환경 지수 상승 흐름");option.value="학급 환경 지수";option.textContent="학급 환경 지수 · 103.1"}
function addPermanentRoles(root=document){if(route()!=="guide")return;const grid=root.matches?.(".content-grid")?root:root.querySelector?.(".content-grid");if(!grid||grid.querySelector(".permanent-roles"))return;const card=document.createElement("section");card.className="card wide permanent-roles";card.innerHTML=`<div class="section-heading"><div><span class="kicker blue">상시직 5명</span><h2>현재 상시직 담당자</h2></div><span class="status open">1학년 13반</span></div><p class="role-intro">학급 운영을 꾸준히 맡는 학생들입니다. 필요한 내용은 각 담당자에게 편하게 알려주세요.</p><div class="role-roster"><article><span class="role-badge">반</span><div><small>반장</small><strong>이루</strong><p>학급 운영을 조정하고 의견을 모읍니다.</p></div></article><article><span class="role-badge">부</span><div><small>부반장</small><strong>최서준</strong><p>반장을 돕고 일정과 공동업무를 챙깁니다.</p></div></article><article><span class="role-badge">의</span><div><small>의장</small><strong>김민재</strong><p>학급회의 순서와 토론 진행을 맡습니다.</p></div></article><article><span class="role-badge">온</span><div><small>온보 편집장</small><strong>고규민</strong><p>학급 소식과 학생 의견을 정리해 온보를 발행합니다.</p></div></article><article><span class="role-badge">서</span><div><small>서기</small><strong>김상우</strong><p>회의 결과와 결정사항을 기록합니다.</p></div></article></div>`;const minimal=grid.querySelector(".minimal");minimal?minimal.before(card):grid.append(card)}
function addCurriculumCard(root=document){addCommunityMarket(root);polishCommunityMarket(root);addPermanentRoles(root)}
const realismObserver=new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===Node.ELEMENT_NODE){polishRealism(node);polishSchoolData(node);polishUpcoming(node);polishDaySchedule(node);addCurriculumCard(node)}})));realismObserver.observe(document.body,{childList:true,subtree:true});
function render(){const r=route(),renderers={home,life,help,meeting,classon,jobs,job,wallet,activities,seating,budget,debug,guide,backup};main.innerHTML=(renderers[r]||home)();polishRealism(main);polishSchoolData(main);polishUpcoming(main);polishDaySchedule(main);addCurriculumCard(main);document.querySelectorAll(".nav-link").forEach(a=>a.classList.toggle("active",a.dataset.section===section(r)));bind();updatePresenter();window.scrollTo(0,0);requestAnimationFrame(()=>main.focus({preventScroll:true}))}
function bind(){main.querySelectorAll("[data-go]").forEach(b=>b.addEventListener("click",()=>go(b.dataset.go)));main.querySelectorAll("[data-filter]").forEach(b=>b.addEventListener("click",()=>{state.noticeFilter=b.dataset.filter;save();render()}));main.querySelectorAll("[data-task]").forEach(b=>b.addEventListener("change",()=>{const id=Number(b.dataset.task);state.tasks=b.checked?[...new Set([...state.tasks,id])]:state.tasks.filter(x=>x!==id);save();announce(b.checked?"체크리스트를 완료 표시했습니다.":"완료 표시를 해제했습니다.")}));main.querySelectorAll("[data-choice]").forEach(b=>b.addEventListener("click",()=>{state.debugChoice=b.dataset.choice;setStep("시연 2 · 수정안 선택");save();render();announce(b.dataset.choice==="apprentice"?"견습 경로 추가를 선택했습니다.":"업무 분할안을 선택했습니다.")}));main.querySelectorAll("[data-action]").forEach(b=>b.addEventListener("click",()=>action(b.dataset.action,b)));main.querySelectorAll("[data-notice-title]").forEach(b=>b.addEventListener("click",()=>{const n=F.notices.find(x=>x.title===b.dataset.noticeTitle);showInfo(n.title,`<p>${n.body}</p><p class="fine">${n.date} · ${n.author} · 가상 공지</p>`)}));main.querySelectorAll("[data-event]").forEach(b=>b.addEventListener("click",()=>{const e=F.events.find(x=>x.title===b.dataset.event);showInfo(e.title,`<p>${e.date} · ${e.meta}</p><p class="fine">실제 학교 일정이 아닌 발표용 예시입니다.</p>`)}));main.querySelectorAll("[data-backup]").forEach(b=>b.addEventListener("click",()=>openBackup(b.dataset.backup)));main.querySelectorAll("[data-demo]").forEach(b=>b.addEventListener("click",()=>demo(b.dataset.demo)))}
function action(name,button){if(name==="apply"){if(state.applied)return;button.disabled=true;state.applied=true;setStep("시연 1 · 지원 완료");save();render();announce("지원이 접수되었습니다. 아래 ‘다음 상태’로 결과를 확인할 수 있습니다.")}else if(name==="next")nextState();else if(name==="save-bid"){const bid=document.getElementById("auction-bid")?.value||"";if(!bid){announce("1~8 ON에서 입찰액을 선택해 주세요.");return}state.auctionBid=bid;save();render();announce(`${bid} ON 비공개 입찰을 저장했습니다. 낙찰될 때만 차감됩니다.`)}else if(name==="save-seat"){const first=document.getElementById("seat-first")?.value||"",second=document.getElementById("seat-second")?.value||"";if(!first||!second){announce("1순위와 2순위를 모두 선택해 주세요.");return}if(first===second){announce("1순위와 2순위는 다른 구역으로 선택해 주세요.");return}state.seatFirst=first;state.seatSecond=second;save();render();announce("희망구역을 비공개로 저장했습니다.")}else if(name==="enact"){if(state.debugChoice!=="apprentice"||state.version==="1.1")return;button.disabled=true;state.version="1.1";setStep("시연 2 · CLASS:ON 1.1");save();render();announce("견습 경로 시험정책을 기록했습니다.")}else if(name==="meal")showMeal();else if(name==="counsel")showCounsel();else if(name==="proposal")showProposal("학급회의 안건 제안");else if(name==="opinion")showProposal("비공개 의견 남기기");else if(name==="notice")showInfo(F.notices[0].title,`<p>${F.notices[0].body}</p><p class="fine">오늘 08:10 · 구현호</p>`);else if(name==="calendar")showInfo("가까운 일정",F.events.map(e=>`<p><strong>${e.date} · ${e.title}</strong><br><span class="fine">${e.meta}</span></p>`).join(""));else if(name==="cleaning")showInfo("청소 도움 요청",`<p>구역 교대나 필요한 조정은 담임에게 비공개로 요청할 수 있습니다.</p><p class="fine">건강·장애·보호되는 결석의 사유와 당사자를 공개하지 않습니다. 청소는 ON으로 면제하지 않습니다.</p>`);else if(name==="activity")showInfo("신청곡 운영 규칙",`<ul class="clean-list"><li>한 곡 신청 2 ON, 공개 대기열에 등록</li><li>청소시간 안에 재생하지 못하면 다음 차례로 이월</li><li>안전과 타인의 권리를 침해하는 내용은 제외</li></ul><p class="fine">사용한 ON은 학생정부 계정으로 이동해 다음 공공노동과 활동 재원이 됩니다.</p>`);else if(name==="project")showInfo("공동프로젝트 운영내역",`<p><strong>프로필 배경·배지 만들기</strong></p><p>학생 기여 목표 30 ON 달성 · 9명 참여 · 김민준 3 ON</p><div class="funding-split modal-funding"><span>학생 기여 <strong>30 ON</strong></span><b>＋</b><span>학생정부 지원 <strong>10 ON</strong></span><b>＝</b><span class="funding-total">집행예산 <strong>40 ON</strong></span></div><ul class="clean-list"><li>학생 기여 목표 달성 뒤 학생정부 지원금 교부</li><li>프로젝트 계정에서 승인된 노동·재료비만 집행</li><li>미사용 지원금은 중앙금고로, 미사용 기여금은 학생에게 반환</li></ul>`);else if(name==="minimal")showInfo("최소모드",`<p>교사의 학급 운영 업무 시간이 2주 연속 30분을 초과하거나 한 주 60분을 넘길 경우, 확장 기능을 축소(최소모드로 전환)합니다.</p><p class="fine">해당 시간 수치는 교사가 상시 제공해야 하는 '보장 시간'이 아니며, 시스템 과부하를 방지하기 위한 '운영 축소 신호'입니다.</p>`)}
function nextState(){if(state.result){go("wallet");return}if(!state.applied){announce("먼저 웹 게시 작업에 지원해 주세요.");go("jobs");return}state.result=true;setStep("시연 1 · 결과 확인·임금 지급");save();go("wallet");announce("업무 완료가 승인되어 세후임금 10.8 ON이 입금되었습니다.")}
function showMeal(){showInfo("오늘의 급식",`<p class="menu-text meal-card-menu">${F.meal.menu.join(" · ")}</p><p class="fine">${F.meal.source}<br>9월 21일 중식 · 08:00 갱신</p>`)}
function showCounsel(){showModal("담임 상담 신청",`<form id="counsel-form"><label>희망 시간대<select required><option value="">선택해 주세요</option><option>점심시간</option><option>방과 후</option><option>담임과 조율</option></select></label><label>상담 방식<select required><option>대면</option><option>비대면</option></select></label><label>간단한 분류<select><option>학교생활</option><option>학업·진로</option><option>관계·기타</option></select></label><label>메모 <span class="fine">(선택)</span><textarea id="counsel-note" rows="3" placeholder="민감한 내용은 웹에 적지 않고 직접 말해도 됩니다."></textarea></label><p class="fine">내용은 서버로 전송되지 않고 이 창을 닫거나 새로고침하면 남지 않습니다. 학생정부와 다른 학생은 볼 수 없습니다.</p><button class="primary" type="submit">발표용 접수 완료</button></form>`,()=>document.getElementById("counsel-form").addEventListener("submit",e=>{e.preventDefault();memoryNote=document.getElementById("counsel-note").value;closeModal();announce("발표용 상담 신청이 접수되었습니다. 실제 전송은 없습니다.")}))}
function showProposal(title){showModal(title,`<form id="proposal-form"><label>제안 분류<select><option>생활 개선</option><option>회의 안건</option><option>규칙 수정</option></select></label><label>한 문장 제안<input required maxlength="80" placeholder="예: 발표자료 공동 점검 시간을 만들어요"></label><p class="fine">민감사건·기본권·개인 처벌은 학생정부 표결 대상이 아니며 담임·학교 절차로 전환합니다.</p><button class="primary" type="submit">발표용 제안 접수</button></form>`,()=>document.getElementById("proposal-form").addEventListener("submit",e=>{e.preventDefault();closeModal();announce("가상 제안이 접수되었습니다.")}))}
function showInfo(title,body){showModal(title,`${body}<button class="primary" data-close>확인</button>`)}
function showModal(title,body,onOpen){modalLayer.hidden=false;modalLayer.innerHTML=`<div class="modal-backdrop" data-close></div><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">${title}</h2><button data-close aria-label="닫기">×</button></div>${body}</section>`;modalLayer.querySelectorAll("[data-close]").forEach(x=>x.addEventListener("click",closeModal));document.addEventListener("keydown",escapeModal);requestAnimationFrame(()=>modalLayer.querySelector("button,select,input,textarea")?.focus());if(onOpen)onOpen()}
function closeModal(){modalLayer.hidden=true;modalLayer.innerHTML="";document.removeEventListener("keydown",escapeModal)}function escapeModal(e){if(e.key==="Escape")closeModal()}
function demo(which){if(which==="one"){state={...defaults,presentOpen:true,step:"시연 1 · 김민준 홈"};save();go("home");render()}else if(which==="two"){state.debugChoice="";state.version="1.0";state.presentOpen=true;setStep("시연 2 · CLASS:ON 1.0");save();go("debug");render()}else if(which==="next")nextState();else if(which==="backup")go("backup");else if(which==="reset")showModal("데모를 초기화할까요?",`<p>지원·결과·정책시험·체크리스트 상태가 모두 최초 상태로 돌아갑니다.</p><div class="modal-actions"><button class="secondary" data-close>취소</button><button class="danger" id="confirm-reset">초기화</button></div>`,()=>document.getElementById("confirm-reset").addEventListener("click",()=>{closeModal();reset()}))}
function openBackup(scene){if(scene==="home"){state.applied=false;state.result=false;go("home")}else if(scene==="job"){state.applied=false;state.result=false;go("job")}else if(scene==="job-applied"){state.applied=true;state.result=false;go("job")}else if(scene==="wallet"){state.applied=true;state.result=true;go("wallet")}else if(scene==="debug"){state.version="1.0";state.debugChoice="";go("debug")}else if(scene==="debug-picked"){state.version="1.0";state.debugChoice="apprentice";go("debug")}else if(scene==="debug-11"){state.version="1.1";state.debugChoice="apprentice";go("debug")}save();render()}
function updatePresenter(){const panel=document.getElementById("present-panel"),toggle=document.getElementById("present-toggle"),quick=document.querySelector(".quick-demo-next");panel.hidden=!state.presentOpen;toggle.setAttribute("aria-expanded",String(state.presentOpen));document.getElementById("present-step").textContent=state.step;if(quick){quick.disabled=!state.applied||state.result;quick.textContent=state.result?"지급 완료":"다음 상태"}}
document.getElementById("present-toggle").addEventListener("click",()=>{state.presentOpen=!state.presentOpen;save()});document.getElementById("present-panel").querySelectorAll("[data-demo]").forEach(b=>b.addEventListener("click",()=>demo(b.dataset.demo)));window.addEventListener("hashchange",render);
document.getElementById("quick-demo-controls")?.querySelectorAll("[data-demo]").forEach(b=>b.addEventListener("click",()=>demo(b.dataset.demo)));
if(document.modelContext?.registerTool){const lifecycle=new AbortController(),register=t=>Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});register({name:"start_class_on_demo",title:"CLASS:ON 시연 시작",description:"가시적 포털을 시연 1 또는 시연 2의 결정적 시작 상태로 이동합니다.",inputSchema:{type:"object",properties:{demo:{type:"string",enum:["work_wallet","policy_debug"]}},required:["demo"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!["work_wallet","policy_debug"].includes(input.demo))throw new Error("demo must be work_wallet or policy_debug");demo(input.demo==="work_wallet"?"one":"two");return{demo:input.demo,state:state.step}}});register({name:"reset_class_on_demo",title:"CLASS:ON 데모 초기화",description:"가시적 데모의 지원·거래·정책시험 상태를 최초 상태로 되돌립니다.",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(){sessionStorage.removeItem(KEY);state={...defaults,presentOpen:true,step:"대기 · 초기 상태"};save();go("home");render();return{reset:true,route:"home"}}})}
debug=debug2;const originalAnnounce=announce;announce=function(message){const friendly={"견습 경로 추가를 선택했습니다.":"‘처음 하는 학생도 함께 뽑기’를 선택했습니다.","업무 분할안을 선택했습니다.":"‘한 일을 두 단계로 나누기’를 선택했습니다.","견습 경로 시험정책을 기록했습니다.":"새 운영방법을 4주 시험하기로 했습니다."};return originalAnnounce(friendly[message]||message)};render();
})();
